/**
 * Deletes the given file or directory if it exists
 */
 protected static void deleteRecursive(File file) {
    if (!file.exists()) {
        throw new IllegalArgumentException("The specified file or directory does not exist");
    }
    if (file.isFile()) {
        deleteFile(file.getName());
    } else {
        String[] fileList = file.list();
        for (String fileName : fileList) {
            deleteRecursive(new File(file, fileName));
        }
        file.delete();
    }
}

