void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (!dirFile.isDirectory()) {
        System.out.println("The given path is not a directory.");
        return;
    }

    File[] files = dirFile.listFiles();
    if (files == null) {
        System.out.println("Could not read files from the directory.");
        return;
    }

    for (File file : files) {
        if (!file.getName().endsWith(".jar")) {
            System.out.println("Skipping file: " + file.getName());
            continue;
        }
        try {
            cpV.add(file.toURI().toURL());
            System.out.println("Added file: " + file.getName());
        } catch (MalformedURLException e) {
            System.out.println("Malformed URL exception.");
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
        // URIs that point to the jar files in the directory
        List<URI> jarUris = new ArrayList<URI>();

        // Get the list of all jar files in the directory
        String[] files = new File(dir).list(new FilenameFilter() {
            @Override
            public boolean accept(File dir, String name) {
                return name.endsWith(".jar");
            }
        });

        // Iterate through the list of files to convert them into URIs
        for (String file : files) {
            URI uri = new File(dir, file).toURI();
            jarUris.add(uri);
        }

        // Iterate through the list of URIs to add them to the classpath Vector
        for (URI uri : jarUris) {
            URL url = uri.toURL();
            cpV.add(url);
        }
    }
}

