public class GreedyCycleCover {
public static <V, E> GraphPath<V, E> getMinimalCovering(Graph<V, E> graph) {
GraphPath<V, E> path = new GraphPath<>(graph);
Set<E> tour = new HashSet<>();

while (path.getVertices().size() < graph.vertexSet().size()) {
V vertex = findNearestVertex(graph, path);
path.addVertex(vertex);
tour.add(graph.edgeSet().stream().filter(edge -> edge.getEndPoint().equals(vertex)).findFirst().get());
}

path.addVertex(graph.getStartPoint());

return path;
}

private static <V, E> V findNearestVertex(Graph<V, E> graph, GraphPath<V, E> path) {
double minDist = Double.POSITIVE_INFINITY;
V nearestVertex = null;

for (V vertex : graph.vertexSet()) {
double dist = graph.getDistance(vertex, path.getEndPoint());
if (dist < minDist) {
minDist = dist;
nearestVertex = vertex;
}
}

return nearestVertex;
}
}

