private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparators(E edge) {
    List<Pair<List<Pair<Integer,Integer>>,E>> separators = new ArrayList<>();
    Set<V> unvisitedVertex = new HashSet<>();
    Set<V> visitedVertex = new HashSet<>();
    for (V v : graph.getVertices()) {
        if (graph.hasEdge(edge, v)) {
            unvisitedVertex.add(v);
        }
    }
    while (!unvisitedVertex.isEmpty()) {
        V vertex = unvisitedVertex.iterator().next();
        List<Pair<List<Pair<Integer,Integer>>,E>> minimalSeparators = computeMinimalSeparator(vertex, edge);
        separators.addAll(minimalSeparators);
        visitedVertex.add(vertex);
        unvisitedVertex.remove(vertex);
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!visitedVertex.contains(neighbor) && !unvisitedVertex.contains(neighbor)) {
                unvisitedVertex.add(neighbor);
            }
        }
    }
    return separators;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeMinimalSeparator(V vertex, E edge) {
    List<Pair<List<Pair<Integer,Integer>>,E>> separators = new ArrayList<>();
    Set<V> exploredVertex = new HashSet<>();
    Queue<V> queue = new ArrayDeque<>();
    queue.add(vertex);
    while (!queue.isEmpty()) {
        V currentVertex = queue.poll();
        exploredVertex.add(currentVertex);
        for (E e : graph.getNeighborEdges(currentVertex, edge)) {
            V neighbor = e.getOther(currentVertex);
            if (!exploredVertex.contains(neighbor)) {
                queue.add(neighbor);
                exploredVertex.add(neighbor);
            }
        }
    }
    List<Pair<List<Pair<Integer,Integer>>,E>> separator = new ArrayList<>();
    separator.add(new Pair<List<Pair<Integer,Integer>>,E>(exploredVertex.stream().map(v -> new Pair<Integer,Integer>(v.getLabel(), edge.getLabel())).collect(Collectors.toList())));
    separators.add(separator);
    return separators;
