    while ( this.tentativeInternId < this.children.size ( ) ) {
      Object object = this.children.get ( this.tentativeInternId );
      if ( object instanceof ThreadSnapshot ) {
        this.tentativeInternId = ( ( ThreadSnapshot ) object ).dump ( );
        continue;
      }
      this.tentativeInternId++;
    }
  }

  public long dump ( ) {
    this.doDump ( );
    return this.tentativeInternId;
  }
}

